INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39011, 'Jeremiah 6:24', 'Jeremiah', 6, 24, '”کله چې مونږ د دوئ په حقله واورېدل، نو زمونږ لاسونو همت پرېښودلو او په لړزېدو شول. لکه څنګه چې يوې ښځې ته د لنګون درد شروع شى دغه شان درد، يرې او وحشت راواخستلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_24.mp3', '', 1761754199, 1761754199),
(39012, 'Jeremiah 6:25', 'Jeremiah', 6, 25, 'بهر مېدان ته مۀ ځئ، او په کوڅو کښې مۀ ګرځئ، ځکه چې زمونږ دشمن تُوره په لاس دے، او هرې خوا ته خوف خور شوے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_25.mp3', '', 1761754199, 1761754199),
(39013, 'Jeremiah 6:26', 'Jeremiah', 6, 26, 'مالِک خُدائ خپلو خلقو ته فرمائى، ”اے زما غوره شوى قومه، د ټاټ جامې واغوندئ او په ايرو کښې ولوغړېږئ. داسې بد بد وير وکړئ لکه څوک يې چې په يک يو زوئ باندې کوى،“ ځکه چې تباه کوونکى به په مونږ ناګهانه حمله وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_26.mp3', '', 1761754199, 1761754199),
(39014, 'Jeremiah 6:27', 'Jeremiah', 6, 27, '”اے يرمياه، ما تۀ د اوسپنې آزمائيونکے جوړ کړې او خپل قوم نه مې اوسپنه جوړه کړه. تۀ زما غوره شوے قوم وآزمايه ترڅو د دوئ د عمل درته پته ولګى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_27.mp3', '', 1761754199, 1761754199),
(39015, 'Jeremiah 6:28', 'Jeremiah', 6, 28, 'هغوئ ټول سخت سرکشه شوى دى، او بدرد وائى او زړونه يې لکه د اوسپنې او پيتلو په شان سخت دى، او دوئ ټول بې‌ايمانى کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_28.mp3', '', 1761754199, 1761754199),
(39016, 'Jeremiah 6:29', 'Jeremiah', 6, 29, 'د بټۍ لاندې خو سخت اور بليږى چې سيکه د سپينو زرو نه جدا کړى خو هغې زما قوم پاک نۀ کړو او بدعمله خلق ترې جدا نۀ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_29.mp3', '', 1761754199, 1761754199),
(39017, 'Jeremiah 6:30', 'Jeremiah', 6, 30, 'هغوئ ته رد شوى سپين زر وئيلے شى، ځکه ما، مالِک خُدائ هغوئ رد کړى دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_30.mp3', '', 1761754199, 1761754199),
(39018, 'Psalms 121:1', 'Psalms', 121, 1, 'سترګې مې غرونو ته نیولې دي ماته له کوم ځایه به مرسته راځي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms121_verse_1.mp3', '', 1761754199, 1761754199),
(39019, 'Psalms 121:2', 'Psalms', 121, 2, 'ما سره کیږي مرسته د څښتن له خوا نه چا چې جوړ کړي اسمان او ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms121_verse_2.mp3', '', 1761754199, 1761754199),
(39020, 'Psalms 121:3', 'Psalms', 121, 3, 'تا به پرېنږدي چې وښویېږې د ستا ساتونکی بېداره پاتې کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms121_verse_3.mp3', '', 1761754199, 1761754199),
(39021, 'Psalms 121:4', 'Psalms', 121, 4, 'په رښتیا څوک چې ساتونکی دی د اسراییلو بېداره پاتې کیږي او هېڅکله نه ویده کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms121_verse_4.mp3', '', 1761754199, 1761754199),
(39022, 'Psalms 121:5', 'Psalms', 121, 5, 'څښتن ساتونکی دی ستا څښتن د سیوري په شان تا سره دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms121_verse_5.mp3', '', 1761754199, 1761754199),
(39023, 'Psalms 121:6', 'Psalms', 121, 6, 'نه به لمر د ورځې تاته کوم زیان رسوي او نه سپوږمۍ په شپه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms121_verse_6.mp3', '', 1761754199, 1761754199),
(39024, 'Psalms 121:7', 'Psalms', 121, 7, 'تا به څښتن له هر ضرره ساتي او تا به خوندي ساتي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms121_verse_7.mp3', '', 1761754199, 1761754199),
(39025, 'Psalms 121:8', 'Psalms', 121, 8, 'په تلو راتللو کې به دې ساتي څښتن له همدا‌اوس نه تر ابده پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms121_verse_8.mp3', '', 1761754199, 1761754199),
(39026, 'Daniel 8:1', 'Daniel', 8, 1, 'د بيلشضر بادشاه د بادشاهۍ په درېم کال، ما دانيال بله رويا وليده، د هغې رويا نه وروستو کومه چې ما مخکښې ليدلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_1.mp3', '', 1761754199, 1761754199),
(39027, 'Daniel 8:2', 'Daniel', 8, 2, 'په رويا کښې ما خپل ځان د سوسه قلعه په خوا کښې د عيلام په صوبه کښې د اولائى نِهر په غاړه ولاړ وليدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_2.mp3', '', 1761754199, 1761754199),
(39028, 'Daniel 8:3', 'Daniel', 8, 3, 'ما وکتل چې هلته زما د وړاندې يو د دوو ښکرو والا ګډ د نِهر په غاړه ولاړ وو، او ښکرونه يې اوږدۀ وُو. او يو ښکر يې د بل نه اوږد وو خو دا وروستو لوئ شوے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_3.mp3', '', 1761754199, 1761754199),
(39029, 'Daniel 8:4', 'Daniel', 8, 4, 'نو ما وليدل چې هغه ګډ د مغرب او شمال او جنوب طرف ته يې ښکرونه وهل. او يو ځناور هم د هغۀ مقابله نۀ شوه کولے، او هيچا څوک هم د هغۀ د زور نه خلاصولے نۀ شُو. څۀ چې يې زړۀ غوښتل هغه يې کول، هغه ډېر طاقتور شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_4.mp3', '', 1761754199, 1761754199),
(39030, 'Daniel 8:5', 'Daniel', 8, 5, 'کله چې ما د دې په حقله سوچ کولو، نو ناڅاپه يو چېلے چې د سترګو په مينځ کښې يې مضبوط ښکر وو د مشرق طرف نه راغلو، هغه زمکې سره د لګېدو نه بغېر د ټولې دُنيا نه راواوړېدو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_5.mp3', '', 1761754199, 1761754199),
(39031, 'Daniel 8:6', 'Daniel', 8, 6, 'هغه د هغه دوو ښکرو والا ګډ له کوم چې ما د نِهر په غاړه ليدلے وو په تېزه او غصه ورغلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_6.mp3', '', 1761754199, 1761754199),
(39032, 'Daniel 8:7', 'Daniel', 8, 7, 'ما هغه وليدو چې په هغه ګډ يې په ډيرې غصې سره حمله وکړه، هغه ګډ يې لاندې راوغورزولو او د هغۀ دواړه ښکرونه يې ټوټه ټوټه کړل. د هغۀ په نسبت هغه ډېر کمزورے وو چې د هغۀ مقابله يې کړے وے، چېلى هغه لاندې په زمکه راوغورزولو او د پښو لاندې يې کړو، او چا هم هغه ګډ د هغۀ د زور نه بچ کولے نۀ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_7.mp3', '', 1761754199, 1761754199),
(39033, 'Daniel 8:8', 'Daniel', 8, 8, 'چېلے ډېر زورَور شو، خو د خپل طاقت آخرى حد ته په رسېدلو باندې د هغۀ لوئ ښکر مات شو، او د دې په ځائ څلور اوچت ښکرونه راوختل چې مخ يې د زمکې څلورو خواو ته وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_8.mp3', '', 1761754199, 1761754199),
(39034, 'Daniel 8:9', 'Daniel', 8, 9, 'په هغې کښې د يو ښکر نه بل راووتلو، چې په شروع کښې ورکوټے وو خو هغه د جنوب او مشرق طرف ته او د اِسرائيل د ښائسته مُلک طرف ته اوږد او طاقتور شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_9.mp3', '', 1761754199, 1761754199),
(39035, 'Daniel 8:10', 'Daniel', 8, 10, 'دا دومره غټ شو چې آسمانى لښکرو ته ورسېدو، او هغۀ څۀ آسمانى لښکر او ستورى لاندې راوغورزول او د پښو لاندې يې کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_10.mp3', '', 1761754199, 1761754199),
(39036, 'Daniel 8:11', 'Daniel', 8, 11, 'هغۀ خپل ځان د آسمانى لښکرو د شهزاده په شان دومره اوچت وګڼلو، او هغۀ ته د روزانه قربانۍ پېش کول يې ختم کړل او د مالِک خُدائ کور يې پليت کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_11.mp3', '', 1761754199, 1761754199),
(39037, 'Daniel 8:12', 'Daniel', 8, 12, 'ځکه د سرکشۍ په وجه، آسمانى لښکرې او روزمره قربانى د ښکر قدرت ته ورکړے شُو. او هغه د هر کار په کولو کښې کامياب شو او حقيقت زمکې ته وغورزولے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_12.mp3', '', 1761754199, 1761754199),
(39038, 'Daniel 8:13', 'Daniel', 8, 13, 'نو بيا ما واورېدل چې يوې مقدسې فرښتې خبرې کولې او بلې مقدسې فرښتې ورته وفرمائيل چې، ”دا کارونه به ترڅو پورې جارى وى کوم چې په رويا کښې وليدلے شُو؟ ترڅو پورې به دا ګناه د روزمره قربانۍ په بدله کښې کيږى؟ ترڅو پورې به آسمانى لښکرې او د مالِک خُدائ کور د پښو لاندې کيږى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_13.mp3', '', 1761754199, 1761754199),
(39039, 'Daniel 8:14', 'Daniel', 8, 14, 'بيا فرښتې ما ته وفرمائيل، ”دا به تر دوه زره او درې سوه ماښامونو او سحرونو پورې وخت واخلى، او د هغې نه وروستو به د مالِک خُدائ کور دوباره مقدس کړے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_14.mp3', '', 1761754199, 1761754199),
(39040, 'Daniel 8:15', 'Daniel', 8, 15, 'کله چې ما دانيال دا رويا کتله او په دې د پوهېدلو کوشش مې کولو، نو زما په وړاندې څوک ودرېدو چې لکه د انسان غوندې ښکارېدو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_15.mp3', '', 1761754199, 1761754199),
(39041, 'Daniel 8:16', 'Daniel', 8, 16, 'او ما د اولائى نِهر د غاړې نه د يو سړى آواز واورېدو چې وې فرمائيل، ”اے جبرائيله، دې سړى ته د دې رويا مطلب ووايه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_16.mp3', '', 1761754199, 1761754199),
(39042, 'Daniel 8:17', 'Daniel', 8, 17, 'کله چې هغه ما ته نزدې راغلو چرته چې زۀ ولاړ وم، نو زۀ وويرېدلم او پړمخې په زمکه پرېوتلم. هغۀ ما ته وفرمائيل، ”اے بنى آدمه، په دې پوهه شه چې د دې رويا تعلق د آخرى زمانې سره دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_17.mp3', '', 1761754199, 1761754199),
(39043, 'Daniel 8:18', 'Daniel', 8, 18, 'کله چې هغۀ ما ته خبرې کولې، زۀ بې‌هوشه وم، په زمکه پړمخې پروت وم. بيا هغۀ زۀ ونيولم او په خپلو پښو يې ودرولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_18.mp3', '', 1761754199, 1761754199),
(39044, 'Daniel 8:19', 'Daniel', 8, 19, 'بيا هغۀ ما ته وفرمائيل، ”زۀ د دې دپاره راغلم چې تا ته ووايم چې وروستو د غضب په وخت کښې به څۀ وشى، ځکه چې د دې رويا تعلق د آخرى زمانې سره دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_19.mp3', '', 1761754199, 1761754199),
(39045, 'Daniel 8:20', 'Daniel', 8, 20, 'کوم د دوو ښکرو ګډ چې تا وليدو دا د مادى او فارس د بادشاهانو نمائندګى کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_20.mp3', '', 1761754199, 1761754199),
(39046, 'Daniel 8:21', 'Daniel', 8, 21, 'دا وېښتو والا چېلے د يونان بادشاه دے، او هغه د سترګو په مينځ کښې لوئ ښکر اولنے بادشاه دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_21.mp3', '', 1761754199, 1761754199),
(39047, 'Daniel 8:22', 'Daniel', 8, 22, 'هغه څلور ښکرونه کوم چې د هغۀ يو مات شوى ښکر په ځائ راوتلو د دې مطلب دا دے چې د اول بادشاهۍ نه به څلور نورې بادشاهۍ جوړې شى خو يو به هم دومره زور طاقت نۀ لرى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_22.mp3', '', 1761754199, 1761754199),
(39048, 'Daniel 8:23', 'Daniel', 8, 23, 'د دوئ د بادشاهۍ په آخرى ورځو کښې کله چې د دې سرکشى او بدکارى آخرى حد ته ورسيږى، نو يو ظالم او ماهر مکار بادشاه به راوچت شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_23.mp3', '', 1761754199, 1761754199),
(39049, 'Daniel 8:24', 'Daniel', 8, 24, 'هغه به ډېر طاقتور شى، خو دا به د دۀ خپل طاقت نۀ وى. هغه به د حېرانونکى تباهۍ سبب شى او څۀ چې هغه کوى په هغې کښې به کامياب شى. هغه به زورَور خلق او د ايماندارانو قوم تباه کړى. ‏', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_24.mp3', '', 1761754199, 1761754199),
(39050, 'Daniel 8:25', 'Daniel', 8, 25, 'د دوکې په سبب به هغه کامياب شى، او هغه به خپل ځان اوچت وګڼى. کله چې هغوئ ځان محفوظ وګڼى، هغه به ناګهانه ډېر خلق تباه کړى او د شهزادګانو د شهزاده خلاف به راپاڅى. خو بيا به هغه تباه شى، خو دا نه چې د انسان په طاقت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_25.mp3', '', 1761754199, 1761754199),
(39051, 'Daniel 8:26', 'Daniel', 8, 26, 'د ماښامونو او سحرونو د قربانيانو کومه رويا چې تا ته ښودلے شوې ده هغه حقيقى ده، خو دا رويا پټه وساته، ځکه چې دا د ډېر لرې مستقبل په حقله ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_26.mp3', '', 1761754199, 1761754199),
(39052, 'Daniel 8:27', 'Daniel', 8, 27, 'زۀ دانيال، ډيرې ورځې خفه او بيمار وم. بيا زۀ پاڅېدم او د بادشاه کارونو له واپس لاړم. زۀ د دې رويا په وجه خفه وم، دا د پوهې نه بهر وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel8_verse_27.mp3', '', 1761754199, 1761754199),
(39053, 'Psalms 116:1', 'Psalms', 116, 1, 'مینه کومه د څښتن سره زه ځکه چې سوال یې اورېدلی زما او قبولې کړې یې زارۍ دي زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms116_verse_1.mp3', '', 1761754199, 1761754199),
(39054, 'Psalms 116:2', 'Psalms', 116, 2, 'هغه نیولی دی خپل غوږ ماته ترڅو ژوندی یم دعاګانې به کومه ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms116_verse_2.mp3', '', 1761754199, 1761754199),
(39055, 'Psalms 116:3', 'Psalms', 116, 3, 'د مرګ په لومه کې راګېر شومه زه د قبر وېره راغله په ما په تکلیف او غم اخته شومه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms116_verse_3.mp3', '', 1761754199, 1761754199),
