(39070, 'Deuteronomy 29:1', 'Deuteronomy', 29, 1, 'دا د هغه لوظ شرطونه دي چې څښتن موسی ته حکم کړی ؤ چې د اسراییلو د خلکو سره یې د موآب په خاوره کې وکړي. دا د هغه لوظ څخه بېل ؤ چې څښتن د هغوی سره د سینا د غره سره کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_1.mp3', '', 1761754199, 1761754199),
(39071, 'Deuteronomy 29:2', 'Deuteronomy', 29, 2, 'موسی د اسراییلو ټول خلک راوغوښتل او ورته ویې ویل: «تاسو په خپله ولیدل چې څښتن په مصر کې په فرعون، د هغه په درباریانو او د هغه په ټول هېواد باندې څه وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_2.mp3', '', 1761754199, 1761754199),
(39072, 'Deuteronomy 29:3', 'Deuteronomy', 29, 3, 'تاسو هغه هیبتناکه بلاګانې، معجزې او هغه عجیبه کارونه ولیدل چې څښتن کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_3.mp3', '', 1761754199, 1761754199),
(39073, 'Deuteronomy 29:4', 'Deuteronomy', 29, 4, 'خو تر نن ورځې پورې هغه تاسو دې ته نه یئ پریښي چې په هغه څه باندې پوه شئ چې په تاسو باندې تېر شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_4.mp3', '', 1761754199, 1761754199),
(39074, 'Deuteronomy 29:5', 'Deuteronomy', 29, 5, 'څښتن څلوېښت کاله تاسو ته په دښته کې لارښوونه وکړه او په دې موده کې ستاسو کالي او څپلۍ هېڅ زاړه نه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_5.mp3', '', 1761754199, 1761754199),
(39075, 'Deuteronomy 29:6', 'Deuteronomy', 29, 6, 'تاسو د خوراک دپاره ډوډۍ نه درلودله او نه مو د څښاک دپاره شراب درلودل، خو څښتن تاسو ته ځانګړي خواړه برابر کړل د دې دپاره چې تاسو په دې باندې پوه شئ چې هغه ستاسو خدای دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_6.mp3', '', 1761754199, 1761754199),
(39076, 'Deuteronomy 29:7', 'Deuteronomy', 29, 7, 'کله چې مونږ دلته راغلو، د حشبون پاچا سیحون او د باشان پاچا عوج په مونږ باندې حمله وکړه. خو مونږ هغوی ته ماتې ورکړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_7.mp3', '', 1761754199, 1761754199),
(39077, 'Deuteronomy 29:8', 'Deuteronomy', 29, 8, 'د هغوی خاوره مو ونیوله او هغه مو د روبین او جاد د قبیلو او منسي د نیمې قبیلې ترمنځ ووېشله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_8.mp3', '', 1761754199, 1761754199),
(39078, 'Deuteronomy 29:9', 'Deuteronomy', 29, 9, 'د دې لوظ د ټولو شرطونو څخه په وفادارۍ سره اطاعت وکړئ، ترڅو تاسو په خپل هر کار کې بریالي اوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_9.mp3', '', 1761754199, 1761754199),
(39079, 'Deuteronomy 29:12', 'Deuteronomy', 29, 12, 'تاسو نن دلته د دې دپاره ولاړ یئ چې په هغه لوظ کې شامل شئ چې خپل څښتن خدای یې ستاسو سره کوي او د هغه شرطونه قبول کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_12.mp3', '', 1761754199, 1761754199),
(39080, 'Deuteronomy 29:16', 'Deuteronomy', 29, 16, 'ستاسو په یاد دي چې په مصر کې مو څنګه ژوند کاوه او څنګه د نورو قومونو د سیمې په لاره باندې تېر شولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_16.mp3', '', 1761754199, 1761754199),
(39081, 'Deuteronomy 29:17', 'Deuteronomy', 29, 17, 'تاسو د هغوی د کرکې وړ بتان ولیدل چې د لرګیو، تیږو، سپینو او سرو زرو څخه جوړ شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_17.mp3', '', 1761754199, 1761754199),
(39082, 'Deuteronomy 29:18', 'Deuteronomy', 29, 18, 'پام کوئ چې هېڅ سړی، ښځه، کورنۍ یا قبیله چې نن دلته ولاړ دي، زمونږ د څښتن خدای څخه به مخ نه اړوي او نه به د نورو قومونو د خدایانو عبادت کوي. که چېرې ستاسو څخه کوم یو د بتانو عبادت کوي هغه به د داسې بوټي په شان وي چې ترخه او زهرجنه مېوه نیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_18.mp3', '', 1761754199, 1761754199),
(39083, 'Deuteronomy 29:19', 'Deuteronomy', 29, 19, 'ګورئ چې نن باید دلته داسې څوک نه وي چې د دې لوظ خبرې واوري او بیاهم خپل ځان ته دا ډاډګېرنه ورکړي چې حتی که چېرې هغه په سرزورۍ سره هم په خپله لاره لاړ شي، د هغه هر کار به په ښه ډول په مخ ځي. داسې کار به تاسو ټول ښه او بد یوشان تباه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_19.mp3', '', 1761754199, 1761754199),
(39084, 'Deuteronomy 29:20', 'Deuteronomy', 29, 20, 'څښتن به داسې سړی ونه بخښي، بلکې د هغه په ضد به د هغه قهر او غضب راوپاریږي او هغه ټول افتونه به چې په دې کتاب کې لیکل شوي دي په هغه باندې نازلیږي، ترڅو څښتن د هغه نوم او نښان د ځمکې د مخ څخه ورک کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_20.mp3', '', 1761754199, 1761754199),
(39085, 'Deuteronomy 29:21', 'Deuteronomy', 29, 21, 'څښتن به د اسراییلو ټولو قبیلو ته هغه یو عبرت وګرځوي او د هغو ټولو لعنتونو سره سم به په هغه باندې افت نازل کړي چې په هغه لوظ کې شامل دي چې د څښتن د شریعت په دې کتاب کې لیکل شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_21.mp3', '', 1761754199, 1761754199),
(39086, 'Deuteronomy 29:24', 'Deuteronomy', 29, 24, 'بیا به د ټولې نړۍ خلک داسې پوښتنې کوي: ‹څښتن ولې د هغوی په هېواد باندې داسې وکړل؟ د دې سخت غضب دلیل څه دی؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_24.mp3', '', 1761754199, 1761754199),
(39087, 'Deuteronomy 29:25', 'Deuteronomy', 29, 25, 'او ځواب به داسې وي: ‹دا ځکه چې دې خلکو د خپلو نیکونو د څښتن خدای لوظ مات کړی دی، هغه لوظ چې څښتن د هغوی سره هغه وخت کړی ؤ چې کله یې هغوی د مصر څخه راوویستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_25.mp3', '', 1761754199, 1761754199),
(39088, 'Deuteronomy 29:26', 'Deuteronomy', 29, 26, 'هغوی د نورو خدایانو عبادت کاوه چې مخکې یې هېڅکله نه ؤ کړی او څښتن د هغو عبادت منع کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_26.mp3', '', 1761754199, 1761754199),
(39089, 'Deuteronomy 29:27', 'Deuteronomy', 29, 27, 'نو څښتن په خپل قوم باندې په قهر شو او د هغوی په خاوره باندې یې هغه ټول افتونه نازل کړل چې په دې کتاب کې لیکل شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy29_verse_27.mp3', '', 1761754199, 1761754199),
