(39100, 'Leviticus 8:9', 'Leviticus', 8, 9, 'لکه څنګه چې څښتن موسی ته امر کړی ؤ، هغه هارون ته لونګۍ ور په سر کړه او د هغې په مخه کې یې د سرو زرو ګل یعنې د وقف کولو پاکه نښه کېښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_9.mp3', '', 1761754199, 1761754199),
(39101, 'Leviticus 8:10', 'Leviticus', 8, 10, 'بیا موسی د مسح کولو تېل واخیستل او هغه یې په خېمه او ټولو شیانو باندې چې په هغې کې وو، وشیندل او په دې ډول یې هغه ټول څښتن ته وقف کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_10.mp3', '', 1761754199, 1761754199),
(39102, 'Leviticus 8:11', 'Leviticus', 8, 11, 'هغه لږ تېل واخیستل او اووه ځلې یې د قربانۍ په ځای باندې وشیندل او د قربانۍ ځای یې د لوښو او تشت سره چې پایه یې درلودله، مسح کړه چې څښتن ته یې وقف کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_11.mp3', '', 1761754199, 1761754199),
(39103, 'Leviticus 8:12', 'Leviticus', 8, 12, 'همدارنګه هغه د مسح کولو لږ تېل د هارون په سر باندې توی کړل او هغه یې د کاهنۍ د دندې دپاره وقف کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_12.mp3', '', 1761754199, 1761754199),
(39104, 'Leviticus 8:13', 'Leviticus', 8, 13, 'بیا لکه څنګه چې څښتن موسی ته امر کړی ؤ، هغه د هارون زامن مخکې راوستل او هغوی ته یې کمیسونه واغوستل، په ملاګانو باندې یې ورته پټۍ ګانې وتړلې او خولۍ ګانې یې ورته په سر کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_13.mp3', '', 1761754199, 1761754199),
(39105, 'Leviticus 8:14', 'Leviticus', 8, 14, 'بیا موسی د ګناه د نذرانې دپاره خوسی راوست او هارون او د هغه زامنو د هغه په سر باندې خپل لاسونه کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_14.mp3', '', 1761754199, 1761754199),
(39106, 'Leviticus 8:15', 'Leviticus', 8, 15, 'موسی خوسی حلال کړ او لږه وینه یې راواخیستله او هغه یې په خپله ګوته باندې د قربانۍ د ځای په ټولو ښکرونو باندې وسولوله، د دې دپاره چې د قربانۍ ځای سپېڅلی شي. بیا هغه پاتې وینه د قربانۍ د ځای په بېخ کې تویه کړه. په دې ډول د قربانۍ ځای سپېڅلی شو او هغه د ګناه په خاطر د قربانۍ د نذرانې دپاره یو مناسب ځای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_15.mp3', '', 1761754199, 1761754199),
(39107, 'Leviticus 8:16', 'Leviticus', 8, 16, 'همدارنګه موسی ټوله وازګه چې په کولمو باندې پرته وه، د اینې ډېره ښه برخه او پښتورګي چې وازګه ورباندې پرته وي، واخیستل او ټول یې د قربانۍ په ځای باندې وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_16.mp3', '', 1761754199, 1761754199),
(39108, 'Leviticus 8:17', 'Leviticus', 8, 17, 'څنګه چې څښتن حکم کړی ؤ هغه پاتې خوسی د پوستکي، غوښې او خوشایو سره واخیست او هغه یې د کمپ څخه دباندې وسوځاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_17.mp3', '', 1761754199, 1761754199),
(39109, 'Leviticus 8:18', 'Leviticus', 8, 18, 'بیا موسی د سوځېدونکې نذرانې دپاره پسه راوست او هارون او د هغه زامنو د پسه په سر باندې خپل لاسونه کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_18.mp3', '', 1761754199, 1761754199),
(39110, 'Leviticus 8:19', 'Leviticus', 8, 19, 'موسی پسه حلال کړ او وینه یې د قربانۍ د ځای په څلورو خواو باندې وشیندله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_19.mp3', '', 1761754199, 1761754199);